// Milestone 3 report generator (docx-js).
// Usage: NODE_PATH=$(npm root -g) node build_report_m3.js results/m3_results.json [out.docx]
// Every number is read from results/m3_results.json (written by run_m3.py --stage collect) or from report_meta.json
// (metadata typed by the team). Sections whose inputs are missing print "[pending: ...]" instead of a number.
const fs = require('fs'); const path = require('path');
const D = require('docx');
const {Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType, Table, TableRow, TableCell, WidthType,
  BorderStyle, ShadingType, ImageRun, PageBreak, Footer, PageNumber, LevelFormat} = D;
const RES_PATH = process.argv[2] || 'results/m3_results.json'; const OUT = process.argv[3] || 'Milestone3_Report.docx';
const R = JSON.parse(fs.readFileSync(RES_PATH, 'utf8')); const FIG = path.join(path.dirname(RES_PATH), 'figures');
const META_PATH = fs.existsSync('report_meta.json') ? 'report_meta.json' : path.join(path.dirname(RES_PATH), 'report_meta.json');
const META = fs.existsSync(META_PATH) ? JSON.parse(fs.readFileSync(META_PATH, 'utf8')) : {};
const isFill = (v) => !v || /^FILL/.test(String(v)) || /^YYYY/.test(String(v));
const INK = '0b0b0b', INK2 = '3f3f3f', ACC = '1f4e79', HEADBG = '1f4e79', ZEBRA = 'f2f5fb', FONT = 'Calibri';
const DS = {lmd: 'LMD-2023 (Dataset A)', mordor: 'Mordor APT29 (Dataset B)'}; const DSS = {lmd: 'LMD-2023', mordor: 'Mordor'};
const MN = {rf: 'Random Forest', lgbm: 'LightGBM', if: 'Isolation Forest', lstm: 'LSTM'}; const MODELS = ['rf', 'lgbm', 'if', 'lstm'];
const has = (x) => x !== null && x !== undefined; const PEND = (w) => `[pending: ${w}]`;
const f2 = (x) => has(x) && isFinite(x) ? Number(x).toFixed(2) : '—'; const f3 = (x) => has(x) && isFinite(x) ? Number(x).toFixed(3) : '—'; const f4 = (x) => has(x) && isFinite(x) ? Number(x).toFixed(4) : '—';
const pct = (x, d = 2) => has(x) && isFinite(x) ? (100 * x).toFixed(d) + '%' : '—'; const num = (x) => has(x) ? Number(x).toLocaleString('en-US') : '—';
const fixminus = (x) => typeof x === 'string' ? x.replace(/(^|[\s(=])-(\d)/g, '$1−$2') : x;

// ---------- helpers (same look as the Milestone-2 report; captions above tables) ----------
function t(text, o = {}) { return new TextRun({text: fixminus(text), font: FONT, size: o.size || 22, bold: o.bold, italics: o.italics, color: o.color || INK}); }
function p(runs, o = {}) { if (typeof runs === 'string') runs = [t(runs, o)];
  return new Paragraph({children: runs, spacing: {line: o.line || 360, after: o.after == null ? 80 : o.after, before: o.before || 0}, alignment: o.align, keepNext: o.keepNext, keepLines: o.keepLines}); }
function h1(x, pb) { return new Paragraph({heading: HeadingLevel.HEADING_1, spacing: {before: pb ? 0 : 280, after: 80}, keepNext: true, pageBreakBefore: !!pb, children: [new TextRun({text: x, font: FONT, size: 28, bold: true, color: ACC})]}); }
function h2(x) { return new Paragraph({heading: HeadingLevel.HEADING_2, spacing: {before: 140, after: 50}, keepNext: true, children: [new TextRun({text: x, font: FONT, size: 24, bold: true, color: INK})]}); }
function bullet(runs) { return new Paragraph({numbering: {reference: 'bl', level: 0}, spacing: {line: 330, after: 40}, children: typeof runs === 'string' ? [t(runs)] : runs}); }
const TS = 9940 / 9360;
function cell(content, w, o = {}) { w = Math.round(w * TS); const kids = Array.isArray(content) ? content : [content];
  const paras = kids.map(c => typeof c === 'string' ? new Paragraph({keepNext: o.keepNext, children: [new TextRun({text: fixminus(c), font: FONT, size: o.size || 16, bold: o.bold, color: o.color || INK})], spacing: {line: 235, after: 15, before: 15}, alignment: o.align}) : c);
  return new TableCell({width: {size: w, type: WidthType.DXA}, shading: o.fill ? {type: ShadingType.CLEAR, fill: o.fill, color: 'auto'} : undefined, margins: {top: 30, bottom: 30, left: 70, right: 70}, verticalAlign: 'center', children: paras}); }
function headerRow(labels, widths, size) { return new TableRow({tableHeader: true, cantSplit: true, children: labels.map((l, i) => cell(l, widths[i], {bold: true, color: 'ffffff', fill: HEADBG, size: size || 16}))}); }
function table(widths, rows) { widths = widths.map(w => Math.round(w * TS)); const b = {style: BorderStyle.SINGLE, size: 2, color: 'bfbfbf'}; const bi = {style: BorderStyle.SINGLE, size: 2, color: 'd9d9d9'};
  return new Table({columnWidths: widths, width: {size: widths.reduce((a, b) => a + b, 0), type: WidthType.DXA}, borders: {top: b, bottom: b, left: b, right: b, insideHorizontal: bi, insideVertical: bi}, rows}); }
function drow(cells, widths, i, o = {}) { const longest = Math.max(...cells.map(c => String(c).length));
  return new TableRow({cantSplit: longest < 260, children: cells.map((c, j) => cell(String(c), widths[j], {size: o.size || 16, fill: (i % 2 === 1) ? ZEBRA : undefined, bold: o.boldCol0 && j === 0, keepNext: o.keepNext, align: ((o.centerFrom != null && j >= o.centerFrom) && !(o.leftCols || []).includes(j)) ? AlignmentType.CENTER : undefined}))}); }
function simpleTable(header, rows, widths, o = {}) { const rs = [headerRow(header, widths, o.size)]; rows.forEach((r, i) => rs.push(drow(r, widths, i, Object.assign({}, o, {keepNext: o.keepTogether && i < rows.length - 1})))); return table(widths, rs); }
let TN = 0, FN = 0; const TREF = {};
const FIGORDER = ['arch_pipeline.png', 'arch_cascade.png', 'sens_rf.png', 'sens_lgbm.png', 'sens_if.png', 'sens_lstm.png', 'cv_models.png', 'cross_dataset.png', 'cascade.png', 'llm_sensitivity.png'];
const FIGN = Object.fromEntries(FIGORDER.map((f, i) => [f, i + 1]));   // figure numbers in document order (checked against the placement counter in figure())
function tcap(key, x) { TN += 1; TREF[key] = TN; const para = new Paragraph({keepNext: true, keepLines: true, spacing: {before: 110, after: 40}, children: [new TextRun({text: `Table ${TN}. `, font: FONT, size: 16, bold: true, color: INK2}), new TextRun({text: fixminus(x), font: FONT, size: 16, italics: true, color: INK2})]}); para.__tcap = true; return para; }
const TREFS = []; // late-bound table references: text with @@key@@ placeholders resolved after all captions exist
function tref(s, o = {}) { const para = p(s, o); para.__tref = true; para.__text = s; para.__opts = o; return para; }
function figure(name, cap, targetW) { const f = path.join(FIG, name); FN++; if (FIGN[name] != null && FIGN[name] !== FN) console.warn(`figure order mismatch: ${name} placed as #${FN}, numbered ${FIGN[name]}`); if (!fs.existsSync(f)) return [p(PEND(`figure ${name}`), {italics: true, color: INK2})];
  const sz = require('child_process').execSync(`python3 -c "from PIL import Image;im=Image.open('${f}');print(im.size[0],im.size[1])"`).toString().trim().split(' ').map(Number);
  const W = Math.min(targetW || 640, 640); const H = Math.round(sz[1] * W / sz[0]);
  return [new Paragraph({keepNext: true, alignment: AlignmentType.CENTER, spacing: {before: 80, after: 30}, children: [new ImageRun({type: 'png', data: fs.readFileSync(f), transformation: {width: W, height: H}})]}),
          new Paragraph({alignment: AlignmentType.CENTER, spacing: {after: 140}, children: [new TextRun({text: `Figure ${FIGN[name] != null ? FIGN[name] : FN}. `, font: FONT, size: 16, bold: true, color: INK2}), new TextRun({text: fixminus(cap), font: FONT, size: 16, italics: true, color: INK2})]})]; }
const mono = (s) => s.trim() === '' ? new Paragraph({spacing: {line: 80, after: 0}, children: [new TextRun({text: '', font: 'Consolas', size: 6})]}) : new Paragraph({spacing: {line: 190, after: 10}, children: [new TextRun({text: s, font: 'Consolas', size: 12, color: INK})]});
const C = [];
const cv = (ds, m) => (R.cv && R.cv[ds] && R.cv[ds][m]) || null; const cvm = (ds, m) => { const r = cv(ds, m); return r ? r.oof_metrics : null; };
const E = R.environment || {}; const CFG = R.config || {}; const FA = R.facts || {}; const CA = R.cascade || {}; const LL = R.llm || {};
const hoursOf = (f) => f && f.start && f.end ? ((new Date(f.end) - new Date(f.start)) / 3.6e6) : null;
const discardShare = (pv) => 1 - pv / (1 - pv);
const bandsOf = (ds) => { const r = cv(ds, 'lgbm'); return r && r.fold_bands ? r.fold_bands : []; };
const topups = (ds) => (CA[ds] && CA[ds].near_threshold_topup_positions) ? CA[ds].near_threshold_topup_positions.length : 0;
const HCP = path.join(path.dirname(RES_PATH), 'host_class_counts.json'); const HC = fs.existsSync(HCP) ? JSON.parse(fs.readFileSync(HCP, 'utf8')) : {};
const hc = (ds, h, k) => (HC[ds] && HC[ds][h]) ? num(HC[ds][h][k]) : '—'; const hcSum = (ds, hs, k) => HC[ds] ? num(hs.reduce((a, h) => a + ((HC[ds][h] || {})[k] || 0), 0)) : '—';
const sec = (x) => has(x) ? (x >= 3600 ? (x / 3600).toFixed(1) + ' h' : x >= 60 ? Math.round(x / 60) + ' min' : Math.round(x) + ' s') : '—';

// ============================================================ derived numbers used in the prose
const OPT = R.optimisation_log || {};
const foldStd = (ds, m) => { const r = cv(ds, m); return r && r.summary && r.summary.f1 ? r.summary.f1.std : null; };
const foldF1 = (ds, m) => { const r = cv(ds, m); return r ? r.fold_metrics.map(x => x.f1) : []; };
const sensRange = (ds, m) => { const s = R.sensitivity && R.sensitivity[ds] && R.sensitivity[ds][m]; if (!s) return null; const f = s.rows.map(r => r.f1), a = s.rows.map(r => r.roc_auc);
  const byHp = {}; s.rows.forEach(r => { (byHp[r.hyperparameter] = byHp[r.hyperparameter] || []).push(r.f1); }); let worst = null, wr = -1;
  for (const [k, v] of Object.entries(byHp)) { const rg = Math.max(...v) - Math.min(...v); if (rg > wr) { wr = rg; worst = k; } }
  const best = s.rows.reduce((x, y) => (y.f1 > x.f1 ? y : x)); return {f1min: Math.min(...f), f1max: Math.max(...f), amin: Math.min(...a), amax: Math.max(...a), worst, wr, best, base: s.rows.find(r => String(r.value) === String(s.base[r.hyperparameter]))}; };
const lgbmIter = (ds) => { const r = cv(ds, 'lgbm'); return r && r.lgbm_iterations ? r.lgbm_iterations.map(x => x.best_iteration) : []; };
const posByFold = (ds, m) => { const r = cv(ds, m); return r ? r.fold_metrics.map(x => x.pos) : []; };
const mPos = posByFold('mordor', 'rf'); const mPosMax = mPos.length ? Math.max(...mPos) : null; const mPosShare = mPosMax && FA.mordor ? mPosMax / FA.mordor.attack_rows : null;
const crossOf = (src, m, fsn, v) => (R.cross || {})[`cross_${src}_to_${src === 'lmd' ? 'mordor' : 'lmd'}_${m}_${fsn}_${v}`] || null;
const crossAll = Object.values(R.cross || {}); const crossMaxAuc = crossAll.length ? Math.max(...crossAll.map(r => r.target_metrics.roc_auc)) : null;
const crossBest = crossAll.length ? crossAll.reduce((a, b) => (b.target_metrics.roc_auc > a.target_metrics.roc_auc ? b : a)) : null;
const nInverted = crossAll.filter(r => r.target_metrics.roc_auc < 0.5).length;
const stageAll = (() => { try { const log = fs.readFileSync(path.join(path.dirname(RES_PATH), 'run.log'), 'utf8'); const d = {}; for (const m of log.matchAll(/==== stage (\w+) done in (\d+)s ====/g)) { (d[m[1]] = d[m[1]] || []).push(Number(m[2])); } return d; } catch (e) { return {}; } })();
const stageDur = Object.fromEntries(Object.entries(stageAll).map(([k, v]) => [k, Math.max(...v)]));          // the full run
const stageExtra = Object.fromEntries(Object.entries(stageAll).map(([k, v]) => [k, v.reduce((a, b) => a + b, 0) - Math.max(...v)]));   // later partial re-runs
const totalCompute = ['ingest', 'features', 'train', 'sensitivity', 'cross', 'cascade'].reduce((a, k) => a + (stageDur[k] || 0), 0);
const totalExtra = ['ingest', 'features', 'train', 'sensitivity', 'cross', 'cascade'].reduce((a, k) => a + (stageExtra[k] || 0), 0);
const DIAG = R.diagnostics || {}; const BL = R.baselines || {};
const thr05 = (ds, m) => { const r = cv(ds, m); return r ? r.oof_metrics_thr05 : null; };
const valShare = (ds, m) => { const r = cv(ds, m); if (!r) return null; const v = r.fold_metrics.filter(f => has(f.n_val) && has(f.n_train)).map(f => f.n_val / (f.n_val + f.n_train)); return v.length ? [Math.min(...v), Math.max(...v)] : null; };
const rangePct = (v, d = 0) => v ? (pct(v[0], d) === pct(v[1], d) ? pct(v[0], d) : pct(v[0], d) + '–' + pct(v[1], d)) : '—';
const lgbmIt = (ds) => { const r = cv(ds, 'lgbm'); return r && r.lgbm_iterations ? r.lgbm_iterations : []; };
const lstmEpochs = (ds) => { const r = cv(ds, 'lstm'); if (!r || !r.training_history) return []; return r.training_history.map(h => { let b = 0; h.forEach((e, i) => { if (e.val_auc > h[b].val_auc) b = i; }); return {run: h.length, best: b + 1}; }); };
const bandDiag = (ds) => (DIAG[ds] && DIAG[ds].band_vs_threshold) || [];
const OV = (ds, k) => (DIAG[ds] && DIAG[ds].error_overlap && DIAG[ds].error_overlap[k]) || null;
const disagree = (ds) => { const o = OV(ds, 'rf_lgbm'); return o ? o.errors_rf + o.errors_lgbm - 2 * o.errors_both : null; };
const rawBands = (ds) => { const r = cv(ds, 'lgbm'); return r && r.fold_bands_raw ? r.fold_bands_raw : null; };
const lstmN = (ds) => { const r = cv(ds, 'lstm'); return r ? r.oof_metrics.n : null; };
const BEFORE = (name) => { const f = path.join(path.dirname(RES_PATH), 'before_lgbm_fix', name); return fs.existsSync(f) ? JSON.parse(fs.readFileSync(f, 'utf8')) : null; };
const lgbmChange = (ds, reduced = false) => { const b = BEFORE(`cv_${ds}_lgbm${reduced ? '_reduced' : ''}.json`); const a = reduced ? (R.cv_reduced && R.cv_reduced.lgbm) : cv(ds, 'lgbm'); if (!b || !a) return null;
  const bi = b.lgbm_iterations.map(x => x.best_iteration), ai = a.lgbm_iterations.map(x => x.best_iteration); const changed = bi.map((v, i) => v !== ai[i] ? `${v}→${ai[i]} (fold ${i})` : null).filter(Boolean);
  return {changed, nChanged: changed.length, f1Before: b.oof_metrics.f1, f1After: a.oof_metrics.f1, aucBefore: b.oof_metrics.roc_auc, aucAfter: a.oof_metrics.roc_auc}; };
const crossLstmN = (src) => { const r = crossOf(src, 'lstm', 'unified', 'raw'); return r ? r.target_metrics.n : null; };
const deltaThr = (ds, m) => { const a = cvm(ds, m), b = thr05(ds, m); return a && b ? a.f1 - b.f1 : null; };
const sgn = (x, d = 3) => (x >= 0 ? '+' : '−') + Math.abs(x).toFixed(d);
const ERR = (ds, m) => { const r = cv(ds, m); return r && r.error_analysis ? r.error_analysis : null; };
const topCat = (o, n = 2) => Object.entries(o || {}).slice(0, n).map(([k, v]) => `${k.replace(/_/g, ' ')} ${pct(v.share, 0)} (vs ${pct(v.share_in_reference, 0)})`).join(', ');
const topEnriched = (o) => { const e = Object.entries(o || {}).filter(([k, v]) => v.share >= 0.05); if (!e.length) return '—'; const b = e.reduce((a, x) => ((x[1].share / Math.max(x[1].share_in_reference, 1e-6)) > (a[1].share / Math.max(a[1].share_in_reference, 1e-6)) ? x : a)); return `${b[0].replace(/_/g, ' ')} ${pct(b[1].share, 0)} (vs ${pct(b[1].share_in_reference, 0)})`; };
const topHost = (o, n = 2) => Object.entries(o || {}).slice(0, n).map(([k, v]) => `${k.split('.')[0]} ${pct(v, 0)}`).join(', ');
const topShift = (o, n = 2) => Object.entries(o || {}).filter(([k, v]) => v.error_median !== v.reference_median).slice(0, n).map(([k, v]) => `${k.replace(/^f_/, '')} ${Number(v.error_median).toLocaleString('en-US', {maximumFractionDigits: 2})} vs ${Number(v.reference_median).toLocaleString('en-US', {maximumFractionDigits: 2})}`).join('; ');

